 void PaintScoreBar(object sender,PaintEventArgs e){e.Graphics.Clear(VisualTheme.HeroPanel);if(assessment==null||assessment.Waiting)return;int x=0,w=scoreBar.ClientSize.Width;foreach(var p in assessment.Points){int next=x+(int)Math.Round((double)w*p.Weight/100);using(var brush=new SolidBrush(p.Status=="pass"?VisualTheme.HeroGreen:p.Status=="attention"?VisualTheme.HeroRed:VisualTheme.HeroAmber))e.Graphics.FillRectangle(brush,x,0,Math.Max(0,next-x-1),scoreBar.Height);x=next;}}
 class Part {
  public string name,status,value,source,time,next,viewStatus;
  public Part(string n,string s,string v,string src,string at){name=n;status=s;value=v;source=src;time=at;}
 }
 class Module {
  public string title,advice;public bool referenceOnly;public List<Part> parts=new List<Part>();
  public Module(string t,string a){title=t;advice=a;}
  public string Status {get {if(referenceOnly)return "reference";if(parts.Count>0&&parts.All(p=>ViewStatus(p)=="checking"))return "checking";if(parts.Any(p=>ViewStatus(p)=="attention"))return "attention";if(parts.Any(p=>ViewStatus(p)=="unknown"))return "unknown";if(parts.Any(p=>ViewStatus(p)=="unconfirmed"))return "unconfirmed";if(parts.Any(p=>ViewStatus(p)=="unchecked"))return parts.Any(p=>ViewStatus(p)=="pass")?"unknown":"unchecked";if(parts.Any(p=>ViewStatus(p)=="pass"))return "pass";if(parts.Any(p=>ViewStatus(p)=="reference"))return "reference";return parts.Count==0?"unchecked":"not-applicable";}}
 }
 static string ViewStatus(Part p){return p.viewStatus??p.status;}
 class EvidenceLine : Panel {
  readonly string name;string badge,hint,value;Color badgeFore,badgeBack,hintColor;readonly Font nameFont,valueFont,badgeFont,hintFont;
