   name=part.name;value=ResultRow.WrapLongTokens(shown);nameFont=new Font(font.FontFamily,VisualTheme.PointSize(9f));valueFont=new Font(font.FontFamily,VisualTheme.PointSize(10f),FontStyle.Bold);badgeFont=new Font(font.FontFamily,VisualTheme.PointSize(9f),FontStyle.Bold);hintFont=new Font(font.FontFamily,VisualTheme.PointSize(9f));
   string t=ViewStatus(part);badge=StatusSymbol(t);badgeFore=VisualTheme.Tone(ModuleTone(t));badgeBack=VisualTheme.Badge(ModuleTone(t));hint=(t=="attention"||t=="unknown")&&!String.IsNullOrWhiteSpace(part.next)?"建议："+part.next:"";hintColor=t=="attention"?Red:Amber;AccessibleName=name+" "+value+" "+badge+" "+hint;
  }
