  static int Needed(string text,Font font,int width){return Measure(text,font,width,true).Height+3;}
  public void SetDisplay(string text){string next=ResultRow.WrapLongTokens(text);if(value==next)return;value=next;AccessibleName=name+" "+value+" "+badge+" "+hint;fittedWidth=-1;Invalidate();}
  public string LineName{get{return name;}}
  public bool UpdatePart(Part part,string shown){string nextValue=ResultRow.WrapLongTokens(shown),nextBadge=StatusSymbol(ViewStatus(part));string nextHint=(part.status=="attention"||part.status=="unknown")&&!String.IsNullOrWhiteSpace(part.next)?"建议："+part.next:"";Color fore=VisualTheme.Tone(ModuleTone(ViewStatus(part)));Color back=VisualTheme.Badge(ModuleTone(ViewStatus(part)));Color h=part.status=="attention"?Red:Amber;if(value==nextValue&&badge==nextBadge&&hint==nextHint&&badgeFore==fore&&badgeBack==back&&hintColor==h)return false;value=nextValue;badge=nextBadge;hint=nextHint;badgeFore=fore;badgeBack=back;hintColor=h;AccessibleName=name+" "+value+" "+badge+" "+hint;fittedWidth=-1;Invalidate();return true;}
  public void Fit(int width){if(fittedWidth==width)return;fittedWidth=width;Width=width;int natural=Measure(badge,badgeFont,0,false).Width+VisualTheme.Px(10);int bw=Math.Min(width,Math.Max(VisualTheme.Px(88),natural));int nw=Math.Min(VisualTheme.Px(100),Math.Max(VisualTheme.Px(72),width/3));int top=VisualTheme.Px(7);badgeRect=new Rectangle(width-bw,VisualTheme.Px(4),bw,Math.Max(VisualTheme.Px(26),Measure(badge,badgeFont,0,false).Height+VisualTheme.Px(8)));nameRect=new Rectangle(0,top,nw,Needed(name,nameFont,nw));int vw=badgeRect.Left-nameRect.Right-VisualTheme.Px(12);
   if(vw>=VisualTheme.Px(95))valueRect=new Rectangle(nameRect.Right+VisualTheme.Px(6),top,vw,Needed(value,valueFont,vw));else valueRect=new Rectangle(0,Math.Max(nameRect.Bottom,badgeRect.Bottom)+VisualTheme.Px(3),width,Needed(value,valueFont,width));
   int bottom=Math.Max(Math.Max(nameRect.Bottom,valueRect.Bottom),badgeRect.Bottom);hintRect=new Rectangle(0,bottom+VisualTheme.Px(2),width,String.IsNullOrEmpty(hint)?0:Needed(hint,hintFont,width));Height=(hintRect.Height>0?hintRect.Bottom:bottom)+VisualTheme.Px(8);}
  public bool Fits {get{bool valid=badgeRect.Right<=Width&&nameRect.Right<=Width&&valueRect.Right<=Width&&hintRect.Right<=Width&&!nameRect.IntersectsWith(badgeRect)&&!valueRect.IntersectsWith(badgeRect)&&!nameRect.IntersectsWith(valueRect);return valid&&nameRect.Height>=Needed(name,nameFont,nameRect.Width)&&valueRect.Height>=Needed(value,valueFont,valueRect.Width)&&(hintRect.Height==0||hintRect.Height>=Needed(hint,hintFont,hintRect.Width))&&hintRect.Bottom<=Height;}}
