  protected override void OnPaint(PaintEventArgs e){if(UiMetrics.on)UiMetrics.linePaint++;base.OnPaint(e);var flags=TextFormatFlags.WordBreak|TextFormatFlags.NoPadding;TextRenderer.DrawText(e.Graphics,name,nameFont,nameRect,Muted,flags);TextRenderer.DrawText(e.Graphics,value,valueFont,valueRect,Ink,flags);using(var b=new SolidBrush(badgeBack))e.Graphics.FillRectangle(b,badgeRect);TextRenderer.DrawText(e.Graphics,badge,badgeFont,badgeRect,badgeFore,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);if(hintRect.Height>0)TextRenderer.DrawText(e.Graphics,hint,hintFont,hintRect,hintColor,flags);using(var p=new Pen(VisualTheme.Divider))e.Graphics.DrawLine(p,0,Height-1,Width,Height-1);}
  protected override void Dispose(bool disposing){if(disposing){if(UiMetrics.on)UiMetrics.lineDispose++;nameFont.Dispose();valueFont.Dispose();badgeFont.Dispose();hintFont.Dispose();}base.Dispose(disposing);}
 }
 class ModuleCard : ResultRow {
  readonly List<EvidenceLine> lines=new List<EvidenceLine>();readonly Label summary=new Label(), metadata=new Label();Module module;int fittedWidth=-1;
  public ModuleCard(Module module,Func<string,string> show,Font font):base(module.title,ModuleBadge(module.Status),"",ModuleTone(module.Status),font){
   heading.Text=FriendlyTitle(module.title);heading.Left=VisualTheme.Px(44);AccessibleName=heading.Text+" "+state.Text;
   if(UiMetrics.on)UiMetrics.cardNew++;Invalidated+=delegate{if(UiMetrics.on)UiMetrics.cardInvalid++;};
   SuspendLayout();this.module=module;body.Visible=false;foreach(var part in module.parts){var line=new EvidenceLine(part,show(part.value),font);lines.Add(line);Controls.Add(line);}
   summary.Text=module.advice;summary.Font=new Font(font.FontFamily,VisualTheme.PointSize(9f));summary.ForeColor=Muted;summary.BackColor=VisualTheme.Card;summary.AutoSize=false;
   var groups=module.parts.Where(p=>!String.IsNullOrEmpty(p.time)).GroupBy(p=>p.source+"\u0001"+p.time).ToList();
   metadata.Text=groups.Count==0?"":String.Join("；",groups.Select(g=>(groups.Count==1?"":String.Join("、",g.Select(p=>p.name).ToArray())+"：")+g.First().source+" "+g.First().time).ToArray());
   metadata.Text=WrapLongTokens(metadata.Text);metadata.Font=new Font(font.FontFamily,VisualTheme.PointSize(9f));metadata.ForeColor=Muted;metadata.BackColor=VisualTheme.Card;metadata.AutoSize=false;Controls.Add(summary);Controls.Add(metadata);ResumeLayout(false);
  }
  static int HeightFor(Label l,int w){return String.IsNullOrEmpty(l.Text)?0:TextRenderer.MeasureText(l.Text,l.Font,new Size(Math.Max(1,w),10000),TextFormatFlags.WordBreak|TextFormatFlags.NoPadding).Height+4;}
  public override void Fit(int width){if(fittedWidth==width)return;fittedWidth=width;SuspendLayout();try{base.Fit(width);int pad=VisualTheme.Px(16),inner=Math.Max(1,width-pad*2),y=Math.Max(heading.Bottom,state.Bottom)+VisualTheme.Px(10);foreach(var line in lines){line.Left=pad;line.Top=y;line.Fit(inner);y=line.Bottom;}summary.Left=pad;summary.Top=y+VisualTheme.Px(8);summary.Width=inner;summary.Height=HeightFor(summary,inner);metadata.Left=pad;metadata.Top=summary.Bottom+VisualTheme.Px(6);metadata.Width=inner;metadata.Height=HeightFor(metadata,inner);Height=Math.Max(VisualTheme.Px(104),metadata.Bottom+pad);}finally{ResumeLayout(false);}}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;int x=VisualTheme.Px(16),y=VisualTheme.Px(18),n=VisualTheme.Px(18);using(var pen=new Pen(VisualTheme.Muted,Math.Max(1,VisualTheme.Px(1)))){string t=module.title;if(t=="当前出口与一致性"){g.DrawEllipse(pen,x,y,n,n);g.DrawLine(pen,x,y+n/2,x+n,y+n/2);g.DrawArc(pen,x+n/4,y,n/2,n,90,180);g.DrawArc(pen,x+n/4,y,n/2,n,270,180);}else if(t=="AI 服务连接"){g.DrawEllipse(pen,x+n/3,y,n/3,n/3);g.DrawEllipse(pen,x,y+n*2/3,n/3,n/3);g.DrawEllipse(pen,x+n*2/3,y+n*2/3,n/3,n/3);g.DrawLine(pen,x+n/2,y+n/3,x+n/6,y+n*2/3);g.DrawLine(pen,x+n/2,y+n/3,x+n*5/6,y+n*2/3);}else if(t=="DNS 解析与路径"){for(int i=0;i<3;i++){int yy=y+VisualTheme.Px(3+i*6);g.DrawLine(pen,x+VisualTheme.Px(6),yy,x+n,yy);g.DrawEllipse(pen,x,yy-VisualTheme.Px(1),VisualTheme.Px(2),VisualTheme.Px(2));}}else if(t=="IPv6 通路"){g.DrawRectangle(pen,x,y+n/4,n,n/2);g.DrawLine(pen,x+n/4,y+n/4,x+n/4,y+n*3/4);g.DrawLine(pen,x+n/2,y+n/4,x+n/2,y+n*3/4);g.DrawLine(pen,x+n*3/4,y+n/4,x+n*3/4,y+n*3/4);}else if(t=="WebRTC / UDP"){g.DrawArc(pen,x,y,n,n,200,140);g.DrawArc(pen,x+n/4,y+n/4,n/2,n/2,200,140);g.DrawEllipse(pen,x+n/2-VisualTheme.Px(1),y+n*3/4,VisualTheme.Px(2),VisualTheme.Px(2));}else{g.DrawRectangle(pen,x+VisualTheme.Px(2),y,Math.Max(2,n-VisualTheme.Px(4)),n);g.DrawLine(pen,x+VisualTheme.Px(5),y+VisualTheme.Px(6),x+n-VisualTheme.Px(5),y+VisualTheme.Px(6));g.DrawLine(pen,x+VisualTheme.Px(5),y+VisualTheme.Px(11),x+n-VisualTheme.Px(5),y+VisualTheme.Px(11));}}}
  public Module Model{get{return module;}}
  static string MetadataText(Module model){var groups=model.parts.Where(p=>!String.IsNullOrEmpty(p.time)).GroupBy(p=>p.source+"\u0001"+p.time).ToList();return WrapLongTokens(groups.Count==0?"":String.Join("；",groups.Select(g=>(groups.Count==1?"":String.Join("、",g.Select(p=>p.name).ToArray())+"：")+g.First().source+" "+g.First().time).ToArray()));}
  public bool UpdateModule(Module next,Func<string,string> show){bool changed=SetRowStatus(ModuleTone(next.Status),ModuleBadge(next.Status));SuspendLayout();try{var old=new List<EvidenceLine>(lines);var updated=new List<EvidenceLine>();foreach(var part in next.parts){var line=old.FirstOrDefault(x=>x.LineName==part.name);if(line==null){line=new EvidenceLine(part,show(part.value),Font);Controls.Add(line);changed=true;}else{old.Remove(line);changed|=line.UpdatePart(part,show(part.value));}updated.Add(line);}foreach(var obsolete in old){Controls.Remove(obsolete);obsolete.Dispose();changed=true;}lines.Clear();lines.AddRange(updated);if(summary.Text!=next.advice){summary.Text=next.advice;changed=true;}string meta=MetadataText(next);if(metadata.Text!=meta){metadata.Text=meta;changed=true;}module=next;if(changed)fittedWidth=-1;}finally{ResumeLayout(false);}return changed;}
  public void UpdateValues(Func<string,string> show){bool changed=false;for(int i=0;i<lines.Count;i++){string before=lines[i].TextSummary;lines[i].SetDisplay(show(module.parts[i].value));changed|=before!=lines[i].TextSummary;}if(changed)fittedWidth=-1;}
  public override bool FitsText{get{bool h=!heading.Bounds.IntersectsWith(state.Bounds)&&state.Right<=Width-VisualTheme.Px(8)&&TextRenderer.MeasureText(heading.Text,heading.Font,Size.Empty,TextFormatFlags.NoPadding).Width<=heading.Width;return h&&lines.All(l=>l.Fits&&l.Right<=Width-VisualTheme.Px(8))&&summary.Height>=HeightFor(summary,summary.Width)&&metadata.Height>=HeightFor(metadata,metadata.Width)&&metadata.Bottom<=Height;}}
