  public bool LinesContrast{get{return lines.All(l=>l.BadgeContrast);}}
  public bool ReadableFonts{get{return heading.Font.Size>=11&&summary.Font.Size>=9&&metadata.Font.Size>=9&&lines.All(l=>l.ReadableFonts);}}
  public int LineCount{get{return lines.Count;}}
  public string Metadata{get{return metadata.Text;}}
  protected override void Dispose(bool disposing){if(disposing){if(UiMetrics.on)UiMetrics.cardDispose++;summary.Font.Dispose();metadata.Font.Dispose();}base.Dispose(disposing);}
 }
 static string ModuleTone(string s){return s=="attention"?"red":s=="unknown"?"yellow":s=="pass"?"green":"gray";}
 static string FriendlyTitle(string title){switch(title){case "当前出口与一致性":return "网络出口（IP）";case "DNS 解析与路径":return "域名解析（DNS）";case "IPv6 通路":return "IPv6 网络";case "WebRTC / UDP":return "浏览器网络（WebRTC）";case "出口属性参考":return "出口位置参考";default:return title;}}
 static string ModuleBadge(string s){return s=="reference"?"仅参考":s=="unconfirmed"?"尚未确认":s=="checking"?"检查中":s=="attention"?"需要核对":s=="unknown"?"部分未验证":s=="pass"?"已观察":s=="unchecked"?"未检查":"未启用";}
 static string StatusSymbol(string s){return s=="checking"?"— 检查中":s=="pass"?"✓ 已观察":s=="attention"?"× 需核对":s=="not-applicable"?"— 未启用":s=="unchecked"?"— 未检查":s=="unconfirmed"?"— 尚未确认":s=="reference"?"— 仅参考":"! 未验证";}
 string DisplayValue(string s){string text=(s??"").Trim();if(text.Contains("；")){string[] values=text.Split('；');var addresses=new List<System.Net.IPAddress>();foreach(string v in values){System.Net.IPAddress parsed;if(!System.Net.IPAddress.TryParse(v.Trim(),out parsed)){addresses.Clear();break;}addresses.Add(parsed);}if(addresses.Count>0)return String.Join("；",addresses.Select(a=>DisplayValue(a.ToString())).ToArray());}System.Net.IPAddress address;if(System.Net.IPAddress.TryParse(text,out address)){if(revealAddress)return address.ToString();if(address.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork){string[] a=address.ToString().Split('.');return a[0]+"."+a[1]+".＊.＊";}var b=address.GetAddressBytes();return b[0].ToString("x2")+b[1].ToString("x2")+":"+b[2].ToString("x2")+b[3].ToString("x2")+":…";}return Engine.Redact(s??"未取得结果");}
 Part FromItem(string name,Item item,DateTimeOffset evaluationTime){if(item==null)return new Part(name,"unchecked","未检查","无本轮证据","");DateTimeOffset when;string time=DateTimeOffset.TryParse(item.observedAt,out when)?when.ToLocalTime().ToString("HH:mm:ss"):"时间未记录";bool historical=!ScoreAssessment.IsFresh(item,evaluationTime,historicalKeys);string prefix=historical?"上次观察，仅供阅读：":"";return new Part(name,historical?"unknown":item.status,prefix+(item.observation??"未取得结果"),Engine.Redact(item.source??"来源未记录"),time){next=historical?"历史观察已过期或依赖出口无法确认；需要时重新完整检查。":Engine.Redact(item.next??"")};}
