  var ipv6path=get("ipv6-path");var ipv6public=get("ipv6-public");var fixedItem=get("ipv4-expected");var pathPart=makePart("系统路径依据",ipv6path);if(ipv6path!=null&&ipv6path.status=="pass"&&ipv6public!=null&&ipv6public.status=="pass"){pathPart.status="unknown";pathPart.value="本机路径与公网探针结果相互矛盾，请重新检查。";}if(ipv6path!=null&&ipv6path.status=="unknown"&&ipv6public!=null&&ipv6public.status=="pass"&&fixedItem!=null&&fixedItem.status=="not-applicable")pathPart.status="reference";if(pathPart.status=="unknown"&&!(ipv6path!=null&&ipv6path.status=="pass"&&ipv6public!=null&&ipv6public.status=="pass")){pathPart.viewStatus="unconfirmed";pathPart.value="本机 IPv6 路径未确认";pathPart.next="";}else if(pathPart.status=="pass")pathPart.value="本次本机路径观察已完成；不代表全部应用";ipv6.parts.Add(pathPart);var v6Sources=items.Where(i=>i.key=="ipv6-source").Take(2).ToList();for(int v=0;v<v6Sources.Count;v++){var source=makePart("IPv6 来源 "+(v+1),v6Sources[v]);if(source.status=="unknown"){source.viewStatus="unconfirmed";source.value=ScoreAssessment.IsFresh(v6Sources[v],at,historicalKeys)?Ipv6Reason(v6Sources[v]):"上次 IPv6 结果已过期，本轮尚未确认";source.next="";}ipv6.parts.Add(source);}var publicPart=makePart("公网 IPv6",ipv6public);if(publicPart.status=="unknown"){publicPart.viewStatus="unconfirmed";publicPart.next="";}ipv6.parts.Add(publicPart);var wfp=get("ipv6-wfp-observation");if(wfp!=null){var wfpPart=makePart("系统规则观察",wfp);wfpPart.viewStatus="unconfirmed";wfpPart.value=!ScoreAssessment.IsFresh(wfp,at,historicalKeys)?"上次系统规则观察已过期，本轮尚未确认":wfp.failureCode=="wfp-access-denied"?"当前权限无法读取系统过滤规则，本项未确认":wfp.failureCode=="wfp-observation-unavailable"?"本轮系统规则未确认":"已观察部分系统规则，不能确认全部路径";wfpPart.next="";ipv6.parts.Add(wfpPart);}modules.Add(ipv6);
