 }
 List<Module> CheckingModules(){var old=rows.Controls.OfType<ModuleCard>().Select(c=>c.Model).ToList();if(old.Count!=6)old=BuildModules(new List<Item>());return old.Select(m=>{var n=new Module(m.title,m.advice);foreach(var p in m.parts)n.parts.Add(new Part(p.name,"checking","检查中","",""){next=""});return n;}).ToList();}
 bool RenderModules(List<Module> modules,bool checking){var cards=rows.Controls.OfType<ModuleCard>().ToList();bool reusable=cards.Count==modules.Count&&rows.Controls.Count==cards.Count&&cards.Select(c=>c.Text).SequenceEqual(modules.Select(m=>m.title));bool changed=false;if(!reusable){while(rows.Controls.Count>0){var old=rows.Controls[0];rows.Controls.Remove(old);old.Dispose();}cards.Clear();foreach(var module in modules){var card=new ModuleCard(module,DisplayValue,Font);cards.Add(card);rows.Controls.Add(card);}changed=true;}else for(int i=0;i<cards.Count;i++){if(checking&&cards[i].MinimumSize.Height==0)cards[i].MinimumSize=new Size(0,cards[i].Height);else if(!checking&&cards[i].MinimumSize.Height!=0)cards[i].MinimumSize=Size.Empty;changed|=cards[i].UpdateModule(modules[i],DisplayValue);}return changed;}
