 void UpdateWidthsCore(){int side=VisualTheme.Px(32),maxWidth=VisualTheme.Px(1200),extra=Math.Max(0,(page.ClientSize.Width-side*2-VisualTheme.Px(25)-maxWidth)/2);int nextSide=side+extra;if(page.Padding.Left!=nextSide||page.Padding.Right!=nextSide)page.Padding=new Padding(nextSide,page.Padding.Top,nextSide,page.Padding.Bottom);int w=Math.Min(maxWidth,Math.Max(VisualTheme.Px(300),page.ClientSize.Width-page.Padding.Horizontal-VisualTheme.Px(25)));LayoutHero(w);probeNotice.MaximumSize=new Size(w,0);if(demoBanner!=null)demoBanner.MaximumSize=new Size(w,0);if(demoPanel!=null)demoPanel.MaximumSize=new Size(w,0);rows.Width=w;int columns=page.ClientSize.Width>=VisualTheme.Px(1080)?3:page.ClientSize.Width>=VisualTheme.Px(760)?2:1,gap=VisualTheme.Px(16),cardWidth=(w-gap*(columns-1))/columns,height=0;for(int i=0;i<rows.Controls.Count;i++){var row=rows.Controls[i] as ResultRow;if(row!=null){row.Margin=new Padding(0,0,(i%columns)<columns-1?gap:0,gap);row.Fit(cardWidth);}}for(int i=0;i<rows.Controls.Count;i+=columns){int max=0;for(int j=i;j<Math.Min(i+columns,rows.Controls.Count);j++)max=Math.Max(max,rows.Controls[j].Height);for(int j=i;j<Math.Min(i+columns,rows.Controls.Count);j++)rows.Controls[j].Height=max;height+=max+gap;}rows.Height=height;foreach(Control c in page.Controls){if(c.Name=="rule")c.Width=w;var label=c as Label;if(label!=null)label.MaximumSize=new Size(w,0);}}
 static string StateText(string status){return status=="pass"?"已观察":status=="attention"?"需要核对":status=="not-applicable"?"未启用":"未验证";}
 void SetRows(IEnumerable<Item> input){if(!measuring){SetRowsCore(input);return;}long start=Stopwatch.GetTimestamp();try{SetRowsCore(input);}finally{measureRows++;measureRowsTicks+=Stopwatch.GetTimestamp()-start;}}
 void SetRowsCore(IEnumerable<Item> input){var items=input.ToList();bool checking=!leavePage&&active&&((busy&&!backgroundChecking)||last==null&&items.Any(i=>i.key=="check"||i.key=="checking"));bool network=!leavePage&&(last!=null||checking);int scrollX=-page.AutoScrollPosition.X,scrollY=-page.AutoScrollPosition.Y;page.SuspendLayout();rows.SuspendLayout();reveal.Visible=network;reveal.Enabled=!checking;if(network){bool changed=RenderModules(checking?CheckingModules():currentModules,checking);sectionTitle.Visible=true;rows.Visible=true;tech.Visible=true;if(changed)UpdateWidths();rows.ResumeLayout(false);if(changed)rows.PerformLayout();page.ResumeLayout(true);if(scrollX!=0||scrollY!=0)page.AutoScrollPosition=new Point(scrollX,scrollY);return;}while(rows.Controls.Count>0){var old=rows.Controls[0];rows.Controls.Remove(old);old.Dispose();}var v4=items.Where(i=>i.key=="ipv4-source"||i.key=="ipv4-compare").ToList();var v6=items.Where(i=>i.key.StartsWith("ipv6-")&&i.key!="ipv6-route-entry").ToList();if(v4.Count>0)AddGroup("公网 IPv4",v4);if(v6.Count>0)AddGroup("IPv6 检查",v6);foreach(var i in items.Where(i=>i.key=="ipv4-expected"))AddGroup("固定出口",new List<Item>{i});foreach(var i in items.Where(i=>i.key=="system-proxy"))AddGroup("网络 / 代理状态",new List<Item>{i});
  bool leaveEvidence=items.Any(i=>i.key=="process"||i.key=="service-scope"||i.key=="runtime-scope");
  if(leaveEvidence){var apps=items.Where(i=>i.key=="process"&&i.role!="后台服务"&&i.role!="后台服务派生进程").ToList();var services=items.Where(i=>i.key=="service-scope"||(i.key=="process"&&(i.role=="后台服务"||i.role=="后台服务派生进程"))).ToList();if(apps.Count==0){bool clear=lastLeave!=null&&(lastLeave.state=="service-only"||lastLeave.state=="not-detected");apps.Add(new Item("process","unknown","本轮收工",clear?"本次未检出应用候选":"应用范围尚未确认","仅反映当前证据。","请在应用内确认任务。"){role=clear?"未检出":"未确认"});}if(services.Count==0)services.Add(new Item("service-scope","unknown","本轮收工","未取得服务检查结果","不代表服务已停止。","请在相关应用中确认任务。"));AddGroup("工作应用",apps);AddGroup("后台服务",services);var runtime=items.Where(i=>i.key=="runtime-scope").ToList();if(runtime.Count==0)runtime.Add(new Item("runtime-scope","unknown","本轮收工","未取得运行时范围结果","不能确认全部退出。","请在相关应用中确认任务。"));AddGroup("检查范围",runtime);foreach(var i in items.Where(i=>i.key=="candidate-connections"))AddGroup("连接观察",new List<Item>{i});}
  foreach(var i in items.Where(i=>!i.key.StartsWith("ipv4-")&&!i.key.StartsWith("ipv6-")&&i.key!="demo"&&i.key!="system-proxy"&&i.key!="process"&&i.key!="service-scope"&&i.key!="runtime-scope"&&i.key!="candidate-connections"))AddGroup(NameOf(i.key),new List<Item>{i});bool hasResults=rows.Controls.Count>0;sectionTitle.Visible=hasResults;rows.Visible=hasResults;tech.Visible=hasResults;UpdateWidths();rows.ResumeLayout(false);rows.PerformLayout();page.ResumeLayout(true);if(scrollX!=0||scrollY!=0)page.AutoScrollPosition=new Point(scrollX,scrollY);}
 static string Ipv6Reason(Item item){switch(item==null?"":item.failureCode){case "no-address-family":return "检测地址未解析出 IPv6";case "dns-failed":return "检测地址解析失败";case "connection-refused":return "IPv6 连接被拒绝";case "connection-failed":return "IPv6 连接未建立";case "timeout":return "IPv6 检测超时";case "tls-failed":return "IPv6 加密连接未完成";case "invalid-http":case "http-failed":return "IPv6 检测未收到有效响应";case "cancelled":return "IPv6 检测已取消";default:return "本次未确认 IPv6 连接";}}
 static string IPv6Name(string key){switch(key){case "ipv6-local":return "本机地址";case "ipv6-gateway":return "网关";case "ipv6-route":return "路由";case "ipv6-tool":return "探针工具";case "ipv6-public":return "公网探针";default:return key;}}
 static string CandidateName(Item item){if(!String.IsNullOrWhiteSpace(item.subject))return Engine.Redact(item.subject);string text=item.observation??"未知候选";int start=text.IndexOf("进程：",StringComparison.Ordinal);if(start>=0){start+="进程：".Length;int end=text.IndexOf('；',start);return Engine.Redact(text.Substring(start,(end<0?text.Length:end)-start));}return Engine.Redact(text);}
 static string FailureReason(Item item){string text=item.observation??"";foreach(string reason in new[]{"DNS 失败","TLS 失败","权限不足","超时","探针或网络错误","用户已取消","未执行","工具不可用"})if(text.IndexOf(reason,StringComparison.OrdinalIgnoreCase)>=0)return "（"+reason+"）";return "";}
 static string ShortResult(string title,List<Item> items){
  var bad=items.Where(i=>i.status=="unknown"||i.status=="attention").ToList();
  if(title=="公网 IPv4"){
   if(bad.Count==0){var comparison=items.FirstOrDefault(i=>i.key=="ipv4-compare");return comparison!=null&&comparison.status=="pass"?"两个来源本次一致":"本次已取得来源观察，未形成双源对照";}
   var parts=new List<string>();int source=0;foreach(var i in items){if(i.key=="ipv4-source"){source++;if(i.status=="unknown"||i.status=="attention")parts.Add("来源 "+source+StateText(i.status)+"（"+Engine.Redact(i.observation??"无结果")+"）");}else if(i.key=="ipv4-compare"&&(i.status=="attention"||i.status=="unknown"&&!items.Any(x=>x.key=="ipv4-source"&&x.status=="unknown")))parts.Add(i.status=="attention"?"两个来源不一致":"双源对照未验证");}
   return String.Join("；",parts.ToArray())+"。保持现有连接，重新检查；仍有问题可查看技术依据。";
  }
  if(title=="IPv6 检查"){
   if(bad.Count==0)return "本轮已有 "+String.Join("、",items.Select(i=>IPv6Name(i.key)).Distinct().ToArray())+" 的观察结果";
   var parts=bad.Select(i=>IPv6Name(i.key)+StateText(i.status)+FailureReason(i)).Distinct().ToArray();
   return String.Join("、",parts)+"。保持现有连接，重新检查；仍未解决可查看技术依据。";
  }
  if(title=="固定出口"){var i=items[0];if(i.status=="not-applicable")return "未启用，不核对固定出口";if(i.status=="unknown"&&(i.observation??"").Contains("尚未填写"))return "已启用但未填写；请在上方选项填写预期 IPv4";if(i.status=="attention")return (i.observation??"").Contains("格式")?"预期 IPv4 格式无效；请在上方选项修改":"观察值与预期不一致；请核对选项和当前连接";return Engine.Redact(i.observation??"未取得结果");}
  if(title=="工作应用"){var found=items.Where(i=>i.status=="attention").ToList();var gaps=items.Where(i=>i.status=="unknown"&&i.role!="未检出").ToList();string gap=gaps.Count==0?"":"；未确认："+String.Join("、",gaps.Select(i=>Engine.Redact(i.observation??"未知")).Distinct().ToArray());if(found.Count>0){string names=String.Join("\n",found.Select(i=>CandidateName(i)+" · 依据："+Engine.Redact(i.source??"未记录")).Distinct().ToArray());return "候选：\n"+names+gap+"。任务状态未知；请保存工作并在应用内正常退出。";}return gaps.Count>0?"应用检查不完整"+gap+"。请在相关应用内确认并保存工作。":"本轮未检出应用候选，仍请确认工作已保存。";}
  if(title=="后台服务"){var candidates=items.Where(i=>i.key=="process"&&i.status=="attention").ToList();bool observed=items.Any(i=>i.serviceEvidence!=null&&(i.serviceEvidence.observedRunning>0||i.serviceEvidence.observedStarting>0));var gaps=items.Where(i=>i.status=="unknown").ToList();string gap=gaps.Count==0?"":"；未确认："+String.Join("、",gaps.Select(i=>Engine.Redact(i.observation??"未知")).Distinct().ToArray());if(candidates.Count>0||observed){string names=candidates.Count>0?"后台服务候选：\n"+String.Join("\n",candidates.Select(i=>CandidateName(i)+" · 依据："+Engine.Redact(i.source??"未记录")).Distinct().ToArray()):"观察到后台服务运行线索";return names+gap+"。任务状态未知，请在相关应用核对；急需离开可保存后自行关机。";}return gaps.Count>0?"服务检查不完整"+gap+"。请在相关应用中核对任务。":"本次未检出已匹配的运行服务，不覆盖全部客户端。";}
  if(title=="检查范围"){bool gap=items.Any(i=>i.status=="unknown"||i.status=="attention");return gap?String.Join("；",items.Where(i=>i.status!="pass").Select(i=>Engine.Redact(i.observation??"未取得结果")).ToArray())+"。请在相关应用中确认任务。":String.Join("；",items.Select(i=>Engine.Redact(i.observation??"已观察")).ToArray());}
  var only=items[0];string observation=Engine.Redact(only.observation??"未取得结果");
  if(title=="网络 / 代理状态"&&only.status=="pass"){string reference="此项仅供配置参考，不能证明流量受保护。";return observation.Contains("未知")?"代理设置还有参考信息未取得："+observation+"。请在 Windows 设置中的“网络和 Internet → 代理”核对。"+reference:observation+"。"+reference;}
  if((only.status=="unknown"||only.status=="attention")&&only.role!="未检出"&&!String.IsNullOrWhiteSpace(only.next))return observation+"\n"+Engine.Redact(only.next);
  return observation;
 }
 void AddGroup(string title,List<Item> items){bool attention=items.Any(x=>x.status=="attention"),unknown=items.Any(x=>x.status=="unknown"),none=items.All(x=>x.status=="not-applicable");string tone=attention?"red":unknown?"yellow":none?"gray":"green",badge=attention?"需要处理":unknown?"未验证":none?"未启用":"本轮已观察";
  if(title=="工作应用"){bool found=items.Any(i=>i.status=="attention"),gap=items.Any(i=>i.status=="unknown"&&i.role!="未检出");tone=found?"red":gap?"yellow":"gray";badge=found?"候选仍在":gap?"未验证":"本次未检出";}
  else if(title=="后台服务"){bool found=items.Any(i=>i.key=="process"&&i.status=="attention")||items.Any(i=>i.serviceEvidence!=null&&(i.serviceEvidence.observedRunning>0||i.serviceEvidence.observedStarting>0));bool gap=items.Any(i=>i.status=="unknown");tone=found||gap?"yellow":"gray";badge=found?"任务待确认":gap?"未验证":"本次未检出";}
  else if(title=="网络 / 代理状态"&&!attention&&!unknown){bool partial=items.Any(i=>(i.observation??"").Contains("未知"));tone=partial?"yellow":"gray";badge=partial?"部分未验证":"仅供参考";}
  else if(title=="固定出口"&&!attention&&!unknown&&!none)badge="本轮匹配";
  else if(title=="公网 IPv4"&&!attention&&!unknown&&!none&&items.Any(i=>i.key=="ipv4-compare"&&i.status=="pass"))badge="双源一致";
  else if(title=="检查状态"&&items.Any(i=>i.key=="checking")){tone="gray";badge="检查中";}
  else if(title=="检查状态"&&items.Any(i=>(i.observation??"").Contains("过期"))){tone="yellow";badge="结果已过期";}
  rows.Controls.Add(new ResultRow(title,badge,ShortResult(title,items),tone,Font));}
 static string NameOf(string key){switch(key){case "checking":case "check":return "检查状态";case "ipv4-compare":return "公网 IPv4";case "ipv4-expected":return "固定出口";case "ipv6-public":return "公网 IPv6";case "ipv6-local":return "本机 IPv6";case "ipv6-route":return "IPv6 路由";case "ipv6-tool":return "IPv6 探针";case "system-proxy":return "网络 / 代理状态";case "connections":return "连接观察";case "service-scope":return "后台服务";case "runtime-scope":return "检查范围";case "process":return "工作应用";case "candidate-connections":return "连接观察";default:return key;}}
 void Initial(){SetAssessment(null);active=false;networkReady=false;leavePage=false;last=null;lastLeave=null;moduleReport=null;currentModules=null;headline.ForeColor=VisualTheme.HeroText;headline.Text="开工前，\n检查一下网络。";advice.Text="点一次开始，检查网络并开启变化提醒。收工时，再检查工作软件是否退出。";probeNotice.Text="检查时会访问外部检测服务，对方可见请求来源地址。\n只读取本机必要状态，不读取账号或个人浏览器资料。具体项目见右上角“使用帮助”。";probeNotice.Visible=!demo;stamp.Text="尚未开始";primary.Text="一键开始办公  →";secondary.Visible=false;monitoring.Text="尚未开启变化提醒";SetRows(new Item[0]);}
 void Primary(){if(!active){if(!ApplyOptions(false))return;active=true;leavePage=false;probeNotice.Visible=false;StartCheck();return;}if(leavePage){if(!busy)StartLeave();else if(cancel!=null){leaveRetryPending=true;returnWorkPending=false;cancel.Cancel();}return;}if(busy){leavePending=true;pending=false;pendingFull=false;monitoring.Text="正在结束本次检查，准备收工";if(cancel!=null)cancel.Cancel();return;}StartLeave();}
 void ReturnToWork(){if(busy||!active)return;leavePage=false;double age=(observationClock()-lastTime).TotalSeconds;if(last!=null&&age>=0&&age<30&&ReusableExtended(retainedExtended,retainedGeneration,generation,evidenceClock())){ShowReport(last);return;}networkReady=false;StartCheck(true,last!=null);}
 void StartCheck(){StartCheck(true);}
 static string V4Baseline(Report r){if(r==null)return null;var list=r.items.Where(i=>i.key=="ipv4-source").ToList();if(list.Count!=2||list.Any(i=>i.status!="pass"||String.IsNullOrWhiteSpace(i.source))||list.Select(i=>i.source).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=2)return null;System.Net.IPAddress a,b;if(!System.Net.IPAddress.TryParse(list[0].observation,out a)||!System.Net.IPAddress.TryParse(list[1].observation,out b)||a.AddressFamily!=System.Net.Sockets.AddressFamily.InterNetwork||!a.Equals(b))return null;return a.ToString()+"|"+String.Join("|",list.Select(i=>i.source.ToLowerInvariant()).OrderBy(x=>x).ToArray());}
 static string V6Baseline(Report r){if(r==null)return null;var path=r.items.FirstOrDefault(x=>x.key=="ipv6-path"&&x.status=="pass"&&(x.identity=="ipv6-path-no-path"||x.identity=="ipv6-path-blocked"));if(path!=null)return "controlled|"+path.identity;var i=r.items.FirstOrDefault(x=>x.key=="ipv6-public");System.Net.IPAddress ip;return i!=null&&i.status=="pass"&&!String.IsNullOrWhiteSpace(i.source)&&System.Net.IPAddress.TryParse(i.observation,out ip)&&ip.AddressFamily==System.Net.Sockets.AddressFamily.InterNetworkV6?ip.ToString()+"|"+i.source.ToLowerInvariant():null;}
 static int FamilyRelation(string a,string b){return a==null||b==null?0:String.Equals(a,b,StringComparison.OrdinalIgnoreCase)?1:2;}
 static int V4Relation(Report a,Report b){string av=V4Baseline(a),bv=V4Baseline(b);if(av==null||bv==null)return 0;string[] x=av.Split('|'),y=bv.Split('|');if(x[1]!=y[1]||x[2]!=y[2])return 0;return FamilyRelation(x[0],y[0]);}
 static int BaselineRelation(Report previous,Report current){int v4=V4Relation(previous,current),v6=FamilyRelation(V6Baseline(previous),V6Baseline(current));return v4==2||v6==2?2:v4==1&&v6==1?1:0;}
 static Item Stale(Item i){return new Item(i.key,"unknown",i.source,i.observation,i.limitation,i.next){observedAt=i.observedAt,subject=i.subject,role=i.role,identity=i.identity,serviceEvidence=i.serviceEvidence,evidencePhase=i.evidencePhase,evidenceScope=i.evidenceScope,failureCode=i.failureCode,rawResult=i.rawResult,transportState="unknown"};}
 static bool Fresh(Item i,DateTimeOffset now){DateTimeOffset at;if(!DateTimeOffset.TryParse(i.observedAt,out at))return false;double age=(now-at).TotalSeconds;return age>=0&&age<300;}
 static bool ReusableExtended(List<Item> items,int evidenceGeneration,int currentGeneration,DateTimeOffset now){return items!=null&&evidenceGeneration==currentGeneration&&new[]{"ext-dns-lookup","ext-ai-claude","ext-ai-openai","ext-ai-grok"}.All(key=>items.Any(i=>i.key==key))&&items.All(i=>Fresh(i,now));} static bool DependencyValid(Item i,int v4,int v6){if(i.key.StartsWith("ext-attr-"))return v4==1;if(i.key=="ext-rtc-compare")return v4==1&&v6==1;return true;}
 static string PrivateRoot(){if(!String.IsNullOrEmpty(configuredWorkRoot))return WorkPaths.PrivateDirectory(configuredWorkRoot);string localBase=WorkPaths.PrivateDirectory(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData));string local=Path.Combine(localBase,"AI开工助手","临时会话");Directory.CreateDirectory(local);return WorkPaths.PrivateDirectory(local);}
 void PublishProgress(int n,int run,int rank,string text,CancellationToken token){if(token.IsCancellationRequested||IsDisposed||!IsHandleCreated)return;try{BeginInvoke((MethodInvoker)delegate{if(IsDisposed||!busy||!active||token.IsCancellationRequested||n!=generation||run!=checkRunId||rank<=progressRank)return;progressRank=rank;progress.Text=text;});}catch(InvalidOperationException){}}
 void StartCheck(bool full){StartCheck(full,!full&&last!=null);}
 void StartCheck(bool full,bool background){if(busy){pending=true;pendingFull|=full;return;}if(!active)return;bool preserveLeave=leavePage;Report previous=last;var prior=retainedExtended;Report originalBaseline=retainedBaseline;int originalGeneration=retainedGeneration;var priorInvalid=new HashSet<string>(retainedInvalidKeys);backgroundChecking=previous!=null&&!preserveLeave;busy=true;primary.Enabled=true;primary.Text=preserveLeave?"重新检查退出  →":"一键结束办公  →";secondary.Text=preserveLeave?"返回办公":"重新检查";secondary.Visible=true;secondary.Enabled=preserveLeave;
  if(backgroundChecking){double age=(observationClock()-displayedAt).TotalSeconds;networkReady=age>=0&&age<30&&networkReady;monitoring.Text="后台复查中 · 上次检查 "+displayedAt.ToString("HH:mm:ss");if(age<0||age>=30)stamp.Text="上次结果，仅供阅读 · "+displayedAt.ToString("HH:mm:ss");}
  else if(!preserveLeave){SetAssessment(null);page.SuspendLayout();headline.MinimumSize=new Size(0,Math.Max(headline.MinimumSize.Height,headline.Height));advice.MinimumSize=new Size(0,Math.Max(advice.MinimumSize.Height,advice.Height));networkReady=false;moduleReport=null;currentModules=null;sectionTitle.Text="本轮检查结果";headline.ForeColor=VisualTheme.HeroMuted;headline.Text="正在检查网络";advice.Text="请稍候；检查期间仍可结束办公。";stamp.Text="检查进行中";last=null;SetRows(new[]{new Item("checking","not-applicable","本轮检查","正在检查网络。","检查尚未完成。","请稍候。")});page.ResumeLayout(true);}  int n=generation;DateTime started=DateTime.Now;bool enabled=appliedExpectedEnabled;string target=appliedExpected;cancel=new CancellationTokenSource();cancel.CancelAfter(60000);CancellationToken token=cancel.Token;int thisRun=++checkRunId;progressRank=1;progress.Text=full?"正在检查本机网络和出口":"正在复查网络";stageProgress=delegate(int rank,string text){PublishProgress(n,thisRun,rank,text,token);};
  ThreadPool.QueueUserWorkItem(delegate{Report report;DateTime baselineAt=DateTime.Now;long baselineTick=monotonicClock();List<Item> nextRaw=prior;Report nextBase=originalBaseline;int nextGeneration=originalGeneration;var nextInvalid=priorInvalid;var nextHistorical=new HashSet<string>();var nextRecent=new HashSet<string>();try{lock(gate){string root=!demo&&full?(capture?"(injected)":PrivateRoot()):null;var wfpBefore=WfpVisibleEvidence.SafeSample(wfpSampler,token);report=run(enabled,target,token);baselineAt=observationClock();baselineTick=monotonicClock();if(!demo){int v4=V4Relation(originalBaseline,report),v6=FamilyRelation(V6Baseline(originalBaseline),V6Baseline(report));bool refresh=full||v4==2||v6==2||!ReusableExtended(prior,originalGeneration,n,evidenceClock());if(refresh){nextRaw=null;nextBase=null;nextGeneration=-1;nextInvalid=new HashSet<string>();if(!token.IsCancellationRequested){if(root==null)root=capture?"(injected)":PrivateRoot();var gathered=collect(report,root,token);report.items.AddRange(gathered);if(!token.IsCancellationRequested){nextRaw=gathered;nextBase=report;nextGeneration=n;}}}else if(prior!=null&&originalGeneration==n){foreach(var item in prior){bool valid=!nextInvalid.Contains(item.key)&&Fresh(item,evidenceClock())&&DependencyValid(item,v4,v6)&&!token.IsCancellationRequested;if(valid){report.items.Add(item);nextRecent.Add(item.key);}else{report.items.Add(Stale(item));nextHistorical.Add(item.key);nextInvalid.Add(item.key);}}}if(token.IsCancellationRequested)report.items.Add(new Item("check","unknown","检查控制","本轮检查超时或取消","未完成不能视为通过。","按需重新检查。"));if(wfpSampler!=null){var wfpAfter=token.IsCancellationRequested?null:WfpVisibleEvidence.SafeSample(wfpSampler,token);report.items.Add(WfpVisibleEvidence.Compare(wfpBefore,wfpAfter));}report=Engine.Assemble(report.items);}}}catch(Exception ex){nextRaw=null;nextBase=null;nextGeneration=-1;nextInvalid=new HashSet<string>();report=Engine.Assemble(new List<Item>{new Item("check","unknown","检查程序",Engine.ErrorC