 }
 string SuggestedAction(Report report,List<Module> modules){var items=report.items;var fixedExit=items.FirstOrDefault(i=>i.key=="ipv4-expected"&&(i.status=="attention"||i.status=="unknown"));if(fixedExit!=null)return "先核对固定出口设置，再检查一次。";if(items.Any(i=>i.key=="ipv4-compare"&&i.status=="attention"))return "两个出口不一致，请核对当前网络后再检查。";if(modules.Any(m=>m.Status=="attention"))return "请先处理需要核对的项目，再检查一次。";if(items.Any(i=>i.key=="ext-dns-lookup"&&i.status=="unknown"))return "域名解析未确认，请核对 DNS 设置后再检查。";var service=items.Where(i=>i.key.StartsWith("ext-ai-")&&i.status=="unknown").ToList();string serviceHelp=ScoreAssessment.ServiceAction(service);if(serviceHelp!=null)return serviceHelp;if(items.Any(i=>i.key=="ipv6-public"&&i.status=="unknown"))return "IPv6 还不能确认，请按卡片原因核对后再检查。";if(!items.Any(i=>i.status=="unknown"||i.status=="attention"))return "可以自行打开 AI 工具试用；登录和模型响应仍需分别核对。";return "请按下方对应项目的原因和建议核对后再检查。";}
 string BriefAdvice(Report report,List<Module> modules,string selectedAction=null){var sentences=new List<string>();var alerts=modules.Where(m=>!m.referenceOnly&&m.parts.Any(p=>p.status=="attention")).Select(m=>FriendlyTitle(m.title)+"（"+String.Join("、",m.parts.Where(p=>p.status=="attention").Select(p=>p.name).ToArray())+"）").ToArray();var failed=report.items.FirstOrDefault(i=>i.key=="check"&&(i.status=="unknown"||i.status=="attention"));string urgent=alerts.Length>0?"需要核对："+String.Join("、",alerts):"";if(failed!=null)urgent+=(urgent.Length>0?"；":"")+"本轮检查未完成："+DisplayValue(failed.observation)+"；"+Engine.Redact(failed.next??"请重新检查");if(urgent.Length>0)sentences.Add(urgent.TrimEnd('。')+"。");var unknown=modules.Where(m=>!m.referenceOnly&&m.parts.Any(p=>p.status=="unknown"||p.status=="unchecked")).Select(m=>{string hint=m.title=="AI 服务连接"&&m.parts.Any(p=>p.status=="unknown"&&p.name.Contains("HTTP 根路径"))?"（HTTP 根路径）":m.title=="IPv6 通路"&&m.parts.Any(p=>(p.status=="unknown"||p.status=="unchecked")&&p.name=="公网探针")?"（公网探针）":"";return FriendlyTitle(m.title)+hint;}).ToArray();var compare=report.items.FirstOrDefault(i=>i.key=="ipv4-compare");string observed=compare!=null&&compare.status=="pass"?"已观察：IPv4 双源一致":"";string pending=unknown.Length>0?"尚未验证："+String.Join("、",unknown):"";string facts=observed+(observed.Length>0&&pending.Length>0?"；":"")+pending;if(facts.Length>0)sentences.Add(facts+"。");sentences.Add(selectedAction??SuggestedAction(report,modules));string joined=String.Join(" ",sentences.ToArray());if(selectedAction!=null&&sentences.Count<3&&!joined.Contains("登录")&&!joined.Contains("模型响应"))sentences.Add("登录和模型响应仍需分别核对。");return String.Join(" ",sentences.ToArray());}
 void ShowReport(Report report){int oldY=-page.AutoScrollPosition.Y,oldX=-page.AutoScrollPosition.X,maxY=Math.Max(0,page.VerticalScroll.Maximum-page.VerticalScroll.LargeChange+1);bool keepBottom=maxY>0&&page.VerticalScroll.Value>=maxY-4;page.SuspendLayout();displayedAt=lastTime;leavePage=false;probeNotice.Visible=false;sectionTitle.Text="本轮基础与最近扩展观察";last=report;DateTimeOffset now=evidenceClock();currentModules=BuildModules(report.items,now);moduleReport=report;var value=ScoreAssessment.Evaluate(report,demo,lastTime,now,historicalKeys);SetAssessment(value);networkReady=!value.Waiting&&value.Level=="green";headline.Text=value.Waiting?"等待本轮结果":value.Headline;headline.ForeColor=value.Waiting?VisualTheme.HeroAmber:value.Level=="red"?VisualTheme.HeroRed:value.Level=="yellow"?VisualTheme.HeroAmber:VisualTheme.HeroText;advice.Text=value.Waiting?"请等待连通检查完成。":value.Action;LayoutHero(hero.Width);stamp.Text="上次检查："+lastTime.ToString("HH:mm:ss")+" · 扩展观察见各项时间";primary.Text="一键结束办公  →";secondary.Text="重新检查";secondary.Visible=true;monitoring.Text="本轮办公中 · 每 30 秒复查";SetRows(report.items);page.ResumeLayout(true);page.PerformLayout();if(keepBottom)page.AutoScrollPosition=new Point(oldX,page.DisplayRectangle.Height);else if(oldX!=0||oldY!=0)page.AutoScrollPosition=new Point(oldX,oldY);}
