 void NetworkChanged(object sender,EventArgs e){if(!active||IsDisposed||!IsHandleCreated)return;try{BeginInvoke((MethodInvoker)delegate{if(!active||IsDisposed)return;bool first=!networkScheduled;long now=Stopwatch.GetTimestamp();if(first)networkFirstTick=now;networkLastTick=now;networkScheduled=true;networkDispatchPending=true;InvalidateEvidence("网络发生变化，之前的结果已过期。");Notify(notices.Signal("network","网络发生变化，正在重新检查。",DateTime.UtcNow));pending=true;pendingFull=true;if(first&&busy&&!networkCheckInFlight&&cancel!=null)cancel.Cancel();networkTimer.Start();});}catch(InvalidOperationException){}}
 void DispatchNetworkChange(){if(!active||IsDisposed){networkTimer.Stop();networkScheduled=false;networkDispatchPending=false;return;}long now=Stopwatch.GetTimestamp();double quiet=(now-networkLastTick)*1000.0/Stopwatch.Frequency,total=(now-networkFirstTick)*1000.0/Stopwatch.Frequency;if(quiet<400&&total<2000)return;networkTimer.Stop();networkScheduled=false;if(busy){pending=true;pendingFull=true;return;}pending=false;pendingFull=false;networkDispatchPending=false;networkCheckInFlight=true;StartCheck(true,last!=null);}
 bool ApplyOptions(bool recheck){string value=expected.Text.Trim();if(expectedEnabled.Checked){System.Net.IPAddress address;if(!System.Net.IPAddress.TryParse(value,out address)||address.AddressFamily!=System.Net.Sockets.AddressFamily.InterNetwork||address.ToString()!=value){optionStatus.ForeColor=Red;optionStatus.Text="请输入完整的 IPv4 地址后再应用";return false;}}bool changed=appliedExpectedEnabled!=expectedEnabled.Checked||appliedExpected!=(expectedEnabled.Checked?value:"");appliedExpectedEnabled=expectedEnabled.Checked;appliedExpected=expectedEnabled.Checked?value:"";optionStatus.ForeColor=Muted;optionStatus.Text=appliedExpectedEnabled?"固定 IPv4 设置已应用":"固定 IPv4 核对未启用";if(changed&&recheck&&active){InvalidateEvidence("固定 IPv4 设置已更新，正在重新检查。");if(busy){pending=true;pendingFull=true;if(cancel!=null)cancel.Cancel();}else StartCheck(true,last!=null);}return true;}
