 static bool CardsDoNotOverlap(Control.ControlCollection controls){for(int i=0;i<controls.Count;i++)for(int j=i+1;j<controls.Count;j++)if(controls[i].Bounds.IntersectsWith(controls[j].Bounds))return false;return true;}
 static bool GeometryValid(MainForm f){var cards=f.rows.Controls.OfType<ModuleCard>().ToArray();if(cards.Length!=6||!f.rows.Visible||cards.Any(c=>!c.Visible||c.Left<0||c.Top<0||c.Right>f.rows.ClientSize.Width||c.Bottom>f.rows.ClientSize.Height)||!CardsDoNotOverlap(f.rows.Controls))return false;int columns=f.page.ClientSize.Width>=VisualTheme.Px(1080)?3:f.page.ClientSize.Width>=VisualTheme.Px(760)?2:1;for(int i=1;i<cards.Length;i++){if(i%columns==0){if(cards[i].Top<=cards[i-1].Top)return false;}else if(cards[i].Top!=cards[i-1].Top||cards[i].Left<=cards[i-1].Left)return false;}return true;}
 static void RecordGeometry(MainForm f,string file,int layouts){var b=new StringBuilder();b.AppendLine("rows_bounds="+f.rows.Bounds+" client="+f.rows.ClientSize+" visible="+f.rows.Visible+" page_client="+f.page.ClientSize+" page_display="+f.page.DisplayRectangle+" scroll="+f.page.AutoScrollPosition+" row_layout_events="+layouts+" update_widths_calls="+f.measureLayouts+" setrows_calls="+f.measureRows);int i=0;foreach(Control card in f.rows.Controls)b.AppendLine("card="+(++i)+" title="+card.Text+" bounds="+card.Bounds+" visible="+card.Visible+" parent_is_rows="+Object.ReferenceEquals(card.Parent,f.rows));b.AppendLine("geometry_valid="+GeometryValid(f));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"logs",file),b.ToString(),Encoding.UTF8);}
 static double Channel(int v){double x=v/255.0;return x<=0.04045?x/12.92:Math.Pow((x+0.055)/1.055,2.4);}
 static double Contrast(Color a,Color b){double x=0.2126*Channel(a.R)+0.7152*Channel(a.G)+0.0722*Channel(a.B),y=0.2126*Channel(b.R)+0.7152*Channel(b.G)+0.0722*Channel(b.B);return (Math.Max(x,y)+0.05)/(Math.Min(x,y)+0.05);}
