 static int VisibleQa(bool hiddenTest){var f=new MainForm(true,true);f.Text="AI开工助手 · 可见 QA（虚构）";f.StartPosition=FormStartPosition.Manual;f.Location=hiddenTest?new Point(-32000,-32000):new Point(20,20);if(hiddenTest)f.Opacity=0;f.ShowInTaskbar=!hiddenTest;f.demoLeave.SelectedIndex=1;int mode=0,step=0;var duration=Stopwatch.StartNew();var log=new StringBuilder();long previous=Stopwatch.GetTimestamp(),maxGap=0,lastStep=0;var pulse=new System.Windows.Forms.Timer{Interval=100};pulse.Tick+=delegate{long now=Stopwatch.GetTimestamp();maxGap=Math.Max(maxGap,now-previous);previous=now;};var drive=new System.Windows.Forms.Timer{Interval=4000};f.run=delegate(bool enabled,string target,CancellationToken token){if(token.WaitHandle.WaitOne(1200))throw new OperationCanceledException();return DemoScenarioCheck(Thread.VolatileRead(ref mode),enabled,target,token);};
  drive.Tick+=delegate{if(duration.ElapsedMilliseconds>65000){log.AppendLine("时间上限：准备结束");f.exiting=true;f.Close();return;}if(f.busy){log.AppendLine("等待虚构采样完成 elapsed_ms="+duration.ElapsedMilliseconds);return;}long at=duration.ElapsedMilliseconds;var work=Stopwatch.StartNew();string name="";switch(step++){case 0:name="开始检查";f.primary.PerformClick();break;case 1:name="显示完整地址";f.reveal.PerformClick();break;case 2:name="隐藏地址";f.reveal.PerformClick();break;case 3:name="向下滚动";f.page.AutoScrollPosition=new Point(0,400);break;case 4:name="窄窗口";f.Width=VisualTheme.Px(500);break;case 5:name="恢复宽窗口";f.Width=VisualTheme.Px(1000);f.page.AutoScrollPosition=new Point(0,0);break;case 6:name="结束办公";f.primary.PerformClick();break;case 7:name="保持收工画面";break;case 8:name="返回办公";f.secondary.PerformClick();break;case 9:name="切换未知样本";Interlocked.Exchange(ref mode,1);f.demoNetwork.SelectedIndex=1;break;case 10:name="重试检查";f.primary.PerformClick();break;case 11:name="查看下半部分";f.page.AutoScrollPosition=new Point(0,400);break;case 12:name="恢复顶部";f.page.AutoScrollPosition=new Point(0,0);break;case 13:name="保持最终画面";break;default:name="结束";break;}log.AppendLine("步骤 "+step+" "+name+" elapsed_ms="+at+" interval_ms="+(at-lastStep)+" action_ms="+work.ElapsedMilliseconds);lastStep=at;if(name=="结束"){f.exiting=true;f.Close();}};
  f.Shown+=delegate{pulse.Start();drive.Start();};f.FormClosed+=delegate{drive.Stop();pulse.Stop();log.AppendLine("虚构采样；总耗时 ms="+duration.ElapsedMilliseconds+"；UI 计时器最长间隔 ms="+(maxGap*1000.0/Stopwatch.Frequency).ToString("0.0")+"。画面仍需人工观察。");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"logs",hiddenTest?"ui-visible-qa-selftest.txt":"ui-visible-qa.txt"),log.ToString(),Encoding.UTF8);drive.Dispose();pulse.Dispose();};Application.Run(f);return 0;}
 static int VisibleReviewQa(bool hidden){int mode=0,step=0;var log=new StringBuilder();var watch=Stopwatch.StartNew();Func<bool,string,CancellationToken,Report> fake=delegate(bool e,string target,CancellationToken token){if(token.WaitHandle.WaitOne(700))throw new OperationCanceledException();return ReviewFixture(Thread.VolatileRead(ref mode));};Func<List<Item>> forbid=delegate{throw new InvalidOperationException("虚构 QA 禁止真实进程采样");};Func<Report,string,CancellationToken,List<Item>> fakeExt=delegate(Report r,string root,CancellationToken token){return new List<Item>{new Item("ext-dns-lookup","pass","虚构 DNS","返回 1 个虚构地址","仅演示",""),new Item("ext-attr-country","pass","虚构数据库","ZZ","仅演示",""),new Item("ext-rtc-compare","unknown","虚构浏览器","未验证","仅演示",""),Functional.HttpEvidence("ext-ai-openai","example.invalid","IPv4",1,2,3,4,404)};};var f=new MainForm(false,true,fake,forbid,fakeExt);f.Text="AI开工助手 · 轮询 QA（虚构）";f.StartPosition=FormStartPosition.Manual;f.Location=hidden?new Point(-32000,-32000):new Point(20,20);if(hidden)f.Opacity=0;f.ShowInTaskbar=!hidden;var drive=new System.Windows.Forms.Timer{Interval=4000};drive.Tick+=delegate{if(watch.ElapsedMilliseconds>65000){f.exiting=true;f.Close();return;}if(f.busy){log.AppendLine("等待模拟采样 elapsed_ms="+watch.ElapsedMilliseconds);return;}int current=step++;string action=current==0?"完整检查":current==4?"单源失败并轻量复查":current==6?"来源恢复并轻量复查":current==8?"再次完整检查":current==14?"结束":"轻量复查";if(current==4)Interlocked.Exchange(ref mode,2);if(current==6)Interlocked.Exchange(ref mode,0);if(current==14){log.AppendLine("步骤 "+(current+1)+" "+action+" elapsed_ms="+watch.ElapsedMilliseconds);f.exiting=true;f.Close();return;}f.active=true;f.StartCheck(current==0||current==8);log.AppendLine("步骤 "+(current+1)+" "+action+" elapsed_ms="+watch.ElapsedMilliseconds+" 六卡="+f.rows.Controls.Count);};f.Shown+=delegate{drive.Start();};f.FormClosed+=delegate{drive.Stop();log.AppendLine("仅虚构采样；总耗时 ms="+watch.ElapsedMilliseconds+"；实际画面仍需观察。");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"logs",hidden?"review-visible-qa-selftest.txt":"review-visible-qa.txt"),log.ToString(),Encoding.UTF8);drive.Dispose();};Application.Run(f);return 0;}
